{
  "name": "pi-side-chat",
  "version": "0.4.0",
  "description": "Pi extension that forks the current conversation into a side chat",
  "type": "module",
  "files": [
    "*.ts",
    "README.md",
    "CHANGELOG.md",
    "banner.png"
  ],
  "keywords": [
    "pi-package",
    "pi",
    "extension",
    "side-chat",
    "coding-agent"
  ],
  "author": "Nico Bailon",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicobailon/pi-side-chat.git"
  },
  "scripts": {
    "test": "tsx --test test/*.test.ts"
  },
  "pi": {
    "extensions": [
      "./index.ts"
    ],
    "video": "https://github.com/nicobailon/pi-side-chat/raw/refs/heads/main/side-chat.mp4"
  },
  "peerDependencies": {
    "@mariozechner/pi-coding-agent": "*",
    "@mariozechner/pi-agent-core": "*",
    "@mariozechner/pi-ai": "*",
    "@mariozechner/pi-tui": "*",
    "@sinclair/typebox": "*"
  },
  "devDependencies": {
    "@mariozechner/pi-coding-agent": "*",
    "@mariozechner/pi-agent-core": "*",
    "@mariozechner/pi-ai": "*",
    "@mariozechner/pi-tui": "*",
    "@sinclair/typebox": "*",
    "tsx": "*"
  }
}

import assert from "node:assert/strict";
import test from "node:test";
import type { AgentMessage } from "@mariozechner/pi-agent-core";
import { forkSurgery, FORKED_MID_EXECUTION_TEXT } from "../fork-surgery.ts";

const assistantToolCall = (id: string): AgentMessage => ({
  role: "assistant",
  content: [{ type: "toolCall", id, name: "read", arguments: { path: "file.ts" } }],
  api: "openai-completions",
  provider: "test",
  model: "test",
  usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, totalTokens: 0, cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 } },
  stopReason: "toolUse",
  timestamp: 1,
} as AgentMessage);

const user = (content: string): AgentMessage => ({ role: "user", content, timestamp: 1 } as AgentMessage);

test("sanitizes a fork opened during a tool call", () => {
  const result = forkSurgery([
    user("main task"),
    assistantToolCall("call-1"),
  ], 42);

  assert.equal(result.length, 2);
  assert.equal(result[0]?.role, "assistant");
  assert.equal(result[1]?.role, "toolResult");
  assert.equal(result[1]?.toolCallId, "call-1");
  assert.equal(result[1]?.content[0]?.type, "text");
  assert.equal(result[1]?.content[0]?.type === "text" ? result[1].content[0].text : "", FORKED_MID_EXECUTION_TEXT);
});

test("cuts trailing main user messages and keeps answered history unchanged", () => {
  const answered = { role: "assistant", content: [{ type: "text", text: "done" }], timestamp: 2 } as AgentMessage;
  const result = forkSurgery([
    user("older task"),
    answered,
    user("pending main question"),
  ]);

  assert.deepEqual(result, [user("older task"), answered]);
});

import assert from "node:assert/strict";
import test from "node:test";
import type { AgentTool } from "@mariozechner/pi-agent-core";
import { visibleWidth } from "@mariozechner/pi-tui";
import { SideChatOverlay, type ForkContext } from "../side-chat-overlay.ts";
import type { DisplayMode } from "../side-chat-layout.ts";

function createOverlay(rows = 40) {
  let renderRequests = 0;
  const displayChanges: DisplayMode[] = [];
  const tui = {
    terminal: { rows, columns: 120 },
    requestRender: () => { renderRequests++; },
  };
  const theme = { fg: (_color: string, text: string) => text };
  const forkContext: ForkContext = {
    messages: [],
    model: {
      id: "test",
      name: "test",
      api: "openai-completions",
      provider: "test",
      baseUrl: "",
      reasoning: false,
      input: ["text"],
      cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
      contextWindow: 1000,
      maxTokens: 100,
    },
    systemPrompt: "test",
    thinkingLevel: "off",
    cwd: "/tmp",
    extensionTools: [],
  };
  const overlay = new SideChatOverlay({
    tui,
    theme,
    forkContext,
    tracker: { writeCount: 0, hasWritten: () => false },
    modelRegistry: { getApiKeyForProvider: async () => "test" },
    sessionManager: { getLeafId: () => null, getEntries: () => [] },
    shortcut: "alt+/",
    fullscreenShortcut: "alt+shift+m",
    onDisplayModeChange: (mode: DisplayMode) => { displayChanges.push(mode); },
    onOverlapWarning: async () => true,
    onUnfocus: () => {},
    onClose: () => {},
  } as unknown as ConstructorParameters<typeof SideChatOverlay>[0]);

  return {
    overlay,
    tui,
    displayChanges,
    get renderRequests() { return renderRequests; },
  };
}

function internals(overlay: SideChatOverlay) {
  return overlay as unknown as {
    agent: { abort: () => void; state: { tools: AgentTool[] } };
    editor: {
      getText: () => string;
      getCursor: () => { line: number; col: number };
      setText: (text: string) => void;
      handleInput: (data: string) => void;
    };
    messages: {
      scrollOffset: number;
      setMessages: (messages: unknown[]) => void;
      handleInput: (data: string) => boolean;
    };
    isStreaming: boolean;
  };
}

test("fullscreen toggle preserves live overlay state and consumes its key", () => {
  const state = createOverlay();
  const privateState = internals(state.overlay);
  const originalAgent = privateState.agent;
  let aborts = 0;
  originalAgent.abort = () => { aborts++; };

  privateState.editor.setText("draft text");
  privateState.editor.handleInput("\x1b[D");
  privateState.messages.setMessages(Array.from({ length: 30 }, (_, index) => ({
    role: "user",
    content: `message ${index}`,
    timestamp: index,
  })));
  state.overlay.render(120);
  privateState.messages.handleInput("\x1b[5~");
  privateState.messages.handleInput("\x1b[5~");
  privateState.isStreaming = true;
  const cursor = privateState.editor.getCursor();

  state.overlay.handleInput("\x1b[77;4u");

  assert.deepEqual(state.displayChanges, ["fullscreen"]);
  assert.equal(internals(state.overlay).agent, originalAgent);
  assert.equal(privateState.editor.getText(), "draft text");
  assert.deepEqual(privateState.editor.getCursor(), cursor);
  assert.equal(privateState.messages.scrollOffset, 10);
  assert.equal(state.overlay.focused, true);
  assert.equal(aborts, 0);
  assert.equal(state.renderRequests, 1);

  const fullscreenLines = state.overlay.render(120);
  assert.equal(fullscreenLines.length, 40);
  assert.match(fullscreenLines.join("\n"), /Alt\+Shift\+M restore/);
  assert.ok(fullscreenLines.every((line) => visibleWidth(line) <= 120));

  state.overlay.handleInput("\x1b[77;4u");

  assert.deepEqual(state.displayChanges, ["fullscreen", "compact"]);
  assert.equal(privateState.editor.getText(), "draft text");
  assert.deepEqual(privateState.editor.getCursor(), cursor);
  assert.equal(privateState.messages.scrollOffset, 10);
  assert.equal(aborts, 0);
  assert.equal(state.renderRequests, 2);

  const compactLines = state.overlay.render(120);
  assert.equal(compactLines.length, 14);
  assert.match(compactLines.join("\n"), /Alt\+Shift\+M fullscreen/);
  assert.ok(compactLines.every((line) => visibleWidth(line) <= 120));
});

test("resize recalculates both display modes without exceeding width", () => {
  const state = createOverlay(24);

  assert.equal(state.overlay.render(80).length, 13);
  state.overlay.handleInput("\x1b[77;4u");
  assert.equal(state.overlay.render(80).length, 24);

  state.tui.terminal.rows = 50;
  assert.equal(state.overlay.render(32).length, 50);
  assert.ok(state.overlay.render(16).every((line) => visibleWidth(line) <= 16));
});

test("fullscreen stays within terminal rows with a multiline editor", () => {
  const state = createOverlay(10);
  const privateState = internals(state.overlay);
  privateState.editor.setText("line one\nline two\nline three\nline four");

  state.overlay.handleInput("\x1b[77;4u");

  assert.equal(state.overlay.render(80).length, 10);
});

test("fullscreen stays within terminals shorter than its fixed chrome", () => {
  const state = createOverlay(5);

  state.overlay.handleInput("\x1b[77;4u");

  assert.equal(state.overlay.render(80).length, 5);
});

import assert from "node:assert/strict";
import test from "node:test";
import {
  getMaxMessageLines,
  getOverlayOptions,
  type DisplayMode,
} from "../side-chat-layout.ts";

const cases: Array<{ mode: DisplayMode; rows: number; editorLines: number; expected: number }> = [
  { mode: "compact", rows: 40, editorLines: 1, expected: 6 },
  { mode: "compact", rows: 40, editorLines: 4, expected: 3 },
  { mode: "fullscreen", rows: 40, editorLines: 1, expected: 32 },
  { mode: "fullscreen", rows: 40, editorLines: 4, expected: 29 },
  { mode: "compact", rows: 10, editorLines: 4, expected: 3 },
  { mode: "fullscreen", rows: 10, editorLines: 4, expected: 0 },
];

for (const value of cases) {
  test(`${value.mode} budget at ${value.rows} rows with ${value.editorLines} editor lines`, () => {
    assert.equal(getMaxMessageLines(value.rows, value.mode, value.editorLines), value.expected);
  });
}

test("display options toggle from compact to fullscreen and back", () => {
  const compact = getOverlayOptions("compact");
  const fullscreen = getOverlayOptions("fullscreen");

  assert.deepEqual(compact, {
    width: "85%",
    maxHeight: "35%",
    anchor: "top-center",
    margin: { top: 1, left: 2, right: 2 },
    nonCapturing: true,
  });
  assert.deepEqual(fullscreen, {
    width: "100%",
    maxHeight: "100%",
    anchor: "top-left",
    margin: 0,
    nonCapturing: true,
  });
  assert.deepEqual(getOverlayOptions("compact"), compact);
  assert.notEqual(getOverlayOptions("compact"), compact);
});

import assert from "node:assert/strict";
import test from "node:test";
import { markFramingMessage, SideChatMessages } from "../side-chat-messages.ts";

const theme = { fg: (_color: string, text: string) => text };

test("viewport resize clamps scroll offset without resetting it", () => {
  const messages = new SideChatMessages(theme as never, 5);
  messages.setMessages(Array.from({ length: 20 }, (_, index) => ({
    role: "user" as const,
    content: `message ${index}`,
    timestamp: index,
  })));
  messages.render(40);

  const state = messages as unknown as { scrollOffset: number };
  messages.handleInput("\x1b[5~");
  messages.handleInput("\x1b[5~");
  assert.equal(state.scrollOffset, 10);

  messages.setMaxVisibleLines(10);
  assert.equal(state.scrollOffset, 10);
  messages.setMaxVisibleLines(35);
  assert.equal(state.scrollOffset, 5);
  messages.setMaxVisibleLines(5);
  assert.equal(state.scrollOffset, 5);
});

test("framing message is sent to the agent but not rendered as a chat bubble", () => {
  const messages = new SideChatMessages(theme as never, 10);
  messages.setMessages([
    markFramingMessage({ role: "user", content: "reference only", timestamp: 1 }),
    { role: "user", content: "latest side question", timestamp: 2 },
  ]);

  const rendered = messages.render(80).join("\n");
  assert.doesNotMatch(rendered, /reference only/);
  assert.match(rendered, /latest side question/);
});

import assert from "node:assert/strict";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import test from "node:test";
import { join } from "node:path";
import type { OverlayOptions } from "@mariozechner/pi-tui";
import sideChatExtension from "../index.ts";

const previousAgentDir = process.env.PI_CODING_AGENT_DIR;
const testAgentDir = mkdtempSync(join(tmpdir(), "pi-side-chat-test-"));

const TEST_MODEL = {
  id: "test",
  name: "test",
  api: "openai-completions",
  provider: "test",
  baseUrl: "",
  reasoning: false,
  input: ["text"],
  cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
  contextWindow: 1000,
  maxTokens: 100,
};
const TEST_THEME = { fg: (_color: string, text: string) => text };

test.before(() => {
  process.env.PI_CODING_AGENT_DIR = testAgentDir;
});

test.after(() => {
  if (previousAgentDir === undefined) {
    delete process.env.PI_CODING_AGENT_DIR;
  } else {
    process.env.PI_CODING_AGENT_DIR = previousAgentDir;
  }
  rmSync(testAgentDir, { recursive: true, force: true });
});

test("extension updates the live overlay options object in place", async () => {
  const commands = new Map<string, { handler: (args: string, context: unknown) => unknown }>();
  const shortcuts = new Map<string, { handler: (context: unknown) => unknown }>();
  let focusCalls = 0;
  let unfocusCalls = 0;

  const pi = {
    on: () => {},
    getThinkingLevel: () => "off",
    registerCommand: (name: string, definition: unknown) => {
      commands.set(name, definition as { handler: (args: string, context: unknown) => unknown });
    },
    registerShortcut: (name: string, definition: unknown) => {
      shortcuts.set(name, definition as { handler: (context: unknown) => unknown });
    },
  };

  sideChatExtension(pi as never);

  const command = commands.get("side");
  const fullscreenShortcut = shortcuts.get("alt+shift+m");
  assert.ok(command);
  assert.ok(shortcuts.get("alt+/"));
  assert.ok(fullscreenShortcut);

  const sessionManager = {
    getEntries: () => [],
    getLeafId: () => null,
  };
  const tui = {
    terminal: { rows: 40, columns: 120 },
    hasOverlay: () => false,
    requestRender: () => {},
  };
  const handle = {
    focus: () => { focusCalls++; },
    unfocus: () => { unfocusCalls++; },
    isFocused: () => true,
  };

  const context = {
    model: TEST_MODEL,
    cwd: "/tmp",
    getSystemPrompt: () => "test",
    modelRegistry: { getApiKeyForProvider: async () => "test" },
    sessionManager,
    ui: {
      notify: () => {},
      confirm: async () => true,
      custom: async (
        factory: (tui: unknown, theme: unknown, keybindings: unknown, done: (result: string) => void) => {
          handleInput: (data: string) => void;
          dispose: () => void;
        },
        options: { overlayOptions: OverlayOptions; onHandle: (overlayHandle: unknown) => void },
      ) => {
        const originalOptions = options.overlayOptions;
        let completed = false;
        const overlay = factory(tui, TEST_THEME, {}, () => { completed = true; });
        options.onHandle(handle);

        assert.deepEqual(originalOptions, {
          width: "85%",
          maxHeight: "35%",
          anchor: "top-center",
          margin: { top: 1, left: 2, right: 2 },
          nonCapturing: true,
        });

        overlay.handleInput("\x1b[77;4u");
        assert.equal(options.overlayOptions, originalOptions);
        assert.deepEqual(originalOptions, {
          width: "100%",
          maxHeight: "100%",
          anchor: "top-left",
          margin: 0,
          nonCapturing: true,
        });

        fullscreenShortcut.handler(context);
        assert.equal(options.overlayOptions, originalOptions);
        assert.deepEqual(originalOptions, {
          width: "85%",
          maxHeight: "35%",
          anchor: "top-center",
          margin: { top: 1, left: 2, right: 2 },
          nonCapturing: true,
        });
        assert.equal(focusCalls, 1);
        assert.equal(unfocusCalls, 0);

        overlay.dispose();
        assert.equal(completed, true);
        return "close";
      },
    },
  };

  await command.handler("", context);
});

test("loads custom shortcuts from the agent dir config", () => {
  writeFileSync(
    join(testAgentDir, "pi-side-chat.json"),
    JSON.stringify({ shortcut: "ctrl+\\", fullscreenShortcut: "ctrl+space" }),
  );

  const shortcuts = new Map<string, unknown>();
  const pi = {
    on: () => {},
    registerCommand: () => {},
    registerShortcut: (name: string, definition: unknown) => {
      shortcuts.set(name, definition);
    },
  };

  sideChatExtension(pi as never);

  assert.ok(shortcuts.has("ctrl+\\"));
  assert.ok(shortcuts.has("ctrl+space"));
  assert.equal(shortcuts.has("alt+/"), false);
  assert.equal(shortcuts.has("alt+shift+m"), false);
});

type TestOverlay = {
  focused: boolean;
  handleInput: (data: string) => void;
  render: (width: number) => string[];
  dispose: () => void;
  ownsOverlayFocusTarget?: (component: unknown) => boolean;
};
type Focusable = { focused: boolean; handleInput: (data: string) => void };
type CustomOverlay = (
  factory: (tui: unknown, theme: unknown, keybindings: unknown, done: (result: string) => void) => TestOverlay,
  options: { onHandle: (overlayHandle: unknown) => void },
) => Promise<string>;

// Kitty keyboard protocol encoding of alt+/.
const ALT_SLASH = "\x1b[47;3u";

function createMainEditor(text: string) {
  return {
    focused: false,
    text,
    handleInput(data: string) { this.text += data; },
  };
}

function registerExtension() {
  // Use default shortcuts regardless of config written by earlier tests.
  rmSync(join(testAgentDir, "pi-side-chat.json"), { force: true });
  const commands = new Map<string, { handler: (args: string, context: unknown) => unknown }>();
  const shortcuts = new Map<string, { handler: (context: unknown) => unknown }>();
  const pi = {
    on: () => {},
    getThinkingLevel: () => "off",
    registerCommand: (name: string, definition: unknown) => {
      commands.set(name, definition as { handler: (args: string, context: unknown) => unknown });
    },
    registerShortcut: (name: string, definition: unknown) => {
      shortcuts.set(name, definition as { handler: (context: unknown) => unknown });
    },
  };
  sideChatExtension(pi as never);
  const command = commands.get("side");
  const toggleShortcut = shortcuts.get("alt+/");
  assert.ok(command);
  assert.ok(toggleShortcut);
  return { command, toggleShortcut };
}

function createContext(custom: CustomOverlay) {
  return {
    model: TEST_MODEL,
    cwd: "/tmp",
    getSystemPrompt: () => "test",
    modelRegistry: { getApiKeyForProvider: async () => "test" },
    sessionManager: { getEntries: () => [], getLeafId: () => null },
    ui: { notify: () => {}, confirm: async () => true, custom },
  };
}

test("Pi overlay handles keep owning focus even when the TUI exposes focus accessors", async () => {
  const { command, toggleShortcut } = registerExtension();
  let handleFocused = false;
  const tui = {
    terminal: { rows: 40, columns: 120 },
    hasOverlay: () => false,
    requestRender: () => {},
    getFocused: () => null,
    setFocus: () => assert.fail("Pi overlay handles must not route focus through the TUI"),
  };
  const handle = {
    focus: () => { handleFocused = true; },
    unfocus: () => { handleFocused = false; },
    isFocused: () => handleFocused,
  };

  const context = createContext(async (factory, options) => {
    const overlay = factory(tui, TEST_THEME, {}, () => {});
    options.onHandle(handle);
    assert.equal(handleFocused, true);
    assert.equal(overlay.ownsOverlayFocusTarget, undefined);

    await toggleShortcut.handler(context);
    assert.equal(handleFocused, false);
    await toggleShortcut.handler(context);
    assert.equal(handleFocused, true);
    overlay.handleInput(ALT_SLASH);
    assert.equal(handleFocused, false);

    overlay.dispose();
    return "close";
  });

  await command.handler("", context);
});

test("OMP-style hosts route focus through the TUI back to the original parent and keep both drafts", async () => {
  const { command, toggleShortcut } = registerExtension();
  const mainEditor = createMainEditor("main draft");
  let focused: Focusable | null = null;
  let visibleOverlay: TestOverlay | undefined;
  const moveFocus = (component: Focusable | null) => {
    if (focused) focused.focused = false;
    focused = component;
    if (component) component.focused = true;
  };
  moveFocus(mainEditor);
  const tui = {
    terminal: { rows: 40, columns: 120 },
    hasOverlay: () => false,
    requestRender: () => {},
    getFocused: () => focused,
    // Mirrors OMP: while an overlay is visible, focus may only move to the overlay
    // or to a target the overlay claims through ownsOverlayFocusTarget.
    setFocus: (component: Focusable | null) => {
      if (visibleOverlay && component !== visibleOverlay && !visibleOverlay.ownsOverlayFocusTarget?.(component)) return;
      moveFocus(component);
    },
  };
  const type = (data: string) => focused?.handleInput(data);
  const sideText = (overlay: TestOverlay) => overlay.render(100).join("\n");

  const context = createContext(async (factory, options) => {
    const overlay = factory(tui, TEST_THEME, {}, () => {});
    visibleOverlay = overlay;
    // Another component takes focus between overlay creation and the handle callback.
    moveFocus(createMainEditor("interloper"));
    options.onHandle({});
    assert.equal(focused, overlay);

    type("side draft");
    await toggleShortcut.handler(context);
    assert.equal(focused, mainEditor);
    type(" main more");
    await toggleShortcut.handler(context);
    assert.equal(focused, overlay);
    type(" side more");
    assert.match(sideText(overlay), /side draft side more/);
    assert.doesNotMatch(sideText(overlay), /main more/);
    assert.equal(mainEditor.text, "main draft main more");

    // The overlay's own shortcut unfocuses through the same TUI route.
    type(ALT_SLASH);
    assert.equal(focused, mainEditor);

    overlay.dispose();
    return "close";
  });

  await command.handler("", context);
});

import assert from "node:assert/strict";
import nodeModule from "node:module";
import test from "node:test";
import type { AgentTool } from "@mariozechner/pi-agent-core";
import { SideChatOverlay, type ForkContext } from "../side-chat-overlay.ts";

const extensionTool: AgentTool = {
  name: "extension_tool",
  label: "extension_tool",
  description: "Test extension tool",
  parameters: { type: "object", properties: {} } as AgentTool["parameters"],
  execute: async () => ({ content: [{ type: "text", text: "ok" }], details: {} }),
};

function createOverlay(
  modelRegistry: object = { getApiKeyForProvider: async () => "test" },
  { Overlay = SideChatOverlay, thinkingLevel = "off" }: { Overlay?: typeof SideChatOverlay; thinkingLevel?: ForkContext["thinkingLevel"] } = {},
) {
  let renderRequests = 0;
  let overlapWarnings = 0;
  const tui = {
    terminal: { rows: 40, columns: 120 },
    requestRender: () => { renderRequests++; },
  };
  const theme = {
    fg: (_color: string, text: string) => text,
  };
  const forkContext: ForkContext = {
    messages: [],
    model: {
      id: "test",
      name: "test",
      api: "side-chat-test-api",
      provider: "test",
      baseUrl: "",
      reasoning: false,
      input: ["text"],
      cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
      contextWindow: 1000,
      maxTokens: 100,
    },
    systemPrompt: "test",
    thinkingLevel,
    cwd: "/tmp",
    extensionTools: [extensionTool],
  };
  const overlay = new Overlay({
    tui,
    theme,
    forkContext,
    tracker: {
      writeCount: 0,
      hasWritten: () => true,
    },
    modelRegistry,
    sessionManager: {
      getSessionId: () => "main-session",
      getLeafId: () => null,
      getEntries: () => [],
    },
    shortcut: "alt+/",
    fullscreenShortcut: "alt+shift+m",
    onDisplayModeChange: () => {},
    onOverlapWarning: async () => {
      overlapWarnings++;
      return false;
    },
    onUnfocus: () => {},
    onClose: () => {},
  } as unknown as ConstructorParameters<typeof SideChatOverlay>[0]);

  return {
    overlay,
    tui,
    model: forkContext.model,
    get renderRequests() { return renderRequests; },
    get overlapWarnings() { return overlapWarnings; },
  };
}

function activeTools(overlay: SideChatOverlay): AgentTool[] {
  return (overlay as unknown as { agent: { state: { tools: AgentTool[] } } }).agent.state.tools;
}

function toolNames(overlay: SideChatOverlay): string[] {
  return activeTools(overlay).map((tool) => tool.name);
}

function count(names: string[], name: string): number {
  return names.filter((candidate) => candidate === name).length;
}

test("Ctrl+T switches tool modes through the current Agent state API", async () => {
  const state = createOverlay();

  assert.match(state.overlay.render(100).join("\n"), /\[Read-only\]/);
  assert.deepEqual(toolNames(state.overlay), ["read", "grep", "find", "ls", "extension_tool", "peek_main"]);

  assert.doesNotThrow(() => state.overlay.handleInput("\x14"));

  const editNames = toolNames(state.overlay);
  assert.match(state.overlay.render(100).join("\n"), /\[Edit\]/);
  for (const name of ["read", "bash", "edit", "write", "extension_tool", "peek_main"]) {
