import type { AgentMessage } from "@mariozechner/pi-agent-core";
import type { ToolResultMessage } from "@mariozechner/pi-ai";

export const FORKED_MID_EXECUTION_TEXT =
  "[forked mid-execution — the main lane was still running this tool call when the side chat opened]";

export function forkSurgery(messages: AgentMessage[], forkTimestamp = Date.now()): AgentMessage[] {
  let end = messages.length;
  while (end > 0 && messages[end - 1].role === "user") end--;

  let start = end;
  while (start > 0) {
    const message = messages[start - 1];
    if (message.role === "toolResult") {
      start--;
      continue;
    }
    if (message.role === "assistant" && hasToolCalls(message)) {
      start--;
      continue;
    }
    break;
  }

  const carryStart = start > 0 && messages[start - 1].role === "user" ? start - 1 : start;
  const region = messages.slice(start, end);
  const cut = end < messages.length || carryStart < start;
  if (!cut && region.length === 0) return messages;

  const callNames = new Map<string, string>();
  const resultIds = new Set<string>();
  for (const message of messages) {
    if (message.role === "assistant") {
      for (const block of message.content) {
        if (block.type === "toolCall") callNames.set(block.id, block.name);
      }
    } else if (message.role === "toolResult") {
      resultIds.add(message.toolCallId);
    }
  }

  const kept = region.filter((message) => message.role !== "toolResult" || callNames.has(message.toolCallId));
  const synthesized: ToolResultMessage[] = [];
  const regionCallIds = new Set<string>();
  for (const message of region) {
    if (message.role !== "assistant") continue;
    for (const block of message.content) {
      if (block.type === "toolCall") regionCallIds.add(block.id);
    }
  }
  for (const id of regionCallIds) {
    if (resultIds.has(id)) continue;
    synthesized.push({
      role: "toolResult",
      toolCallId: id,
      toolName: callNames.get(id) ?? "unknown",
      content: [{ type: "text", text: FORKED_MID_EXECUTION_TEXT }],
      isError: false,
      timestamp: forkTimestamp,
    });
  }

  if (!cut && kept.length === region.length && synthesized.length === 0) return messages;
  return [...messages.slice(0, carryStart), ...kept, ...synthesized];
}

function hasToolCalls(message: AgentMessage): boolean {
  return message.role === "assistant" && message.content.some((block) => block.type === "toolCall");
}

import type { OverlayOptions } from "@mariozechner/pi-tui";

export type DisplayMode = "compact" | "fullscreen";

const FIXED_CHROME_LINES = 7;
const MIN_COMPACT_MESSAGE_LINES = 3;

export function getOverlayOptions(mode: DisplayMode): OverlayOptions {
  if (mode === "fullscreen") {
    return {
      width: "100%",
      maxHeight: "100%",
      anchor: "top-left",
      margin: 0,
      nonCapturing: true,
    };
  }

  return {
    width: "85%",
    maxHeight: "35%",
    anchor: "top-center",
    margin: { top: 1, left: 2, right: 2 },
    nonCapturing: true,
  };
}

export function getMaxMessageLines(
  terminalRows: number,
  mode: DisplayMode,
  editorLines: number,
): number {
  const targetHeight = mode === "fullscreen"
    ? terminalRows
    : Math.floor(terminalRows * 0.35);

  const minimum = mode === "fullscreen" ? 0 : MIN_COMPACT_MESSAGE_LINES;
  return Math.max(minimum, targetHeight - editorLines - FIXED_CHROME_LINES);
}

import { resolve } from "node:path";

export class FileActivityTracker {
  private written = new Set<string>();

  trackWrite(path: string, cwd: string) {
    this.written.add(this.normalize(path, cwd));
  }

  hasWritten(path: string, cwd: string): boolean {
    return this.written.has(this.normalize(path, cwd));
  }

  get writeCount(): number {
    return this.written.size;
  }

  private normalize(path: string, cwd: string): string {
    return resolve(cwd, path);
  }
}

import type { AgentTool } from "@mariozechner/pi-agent-core";
import type { FileActivityTracker } from "./file-activity-tracker.ts";

export function wrapToolsWithOverlapDetection(
  tools: AgentTool[],
  tracker: FileActivityTracker,
  cwd: string,
  confirmOverlap: (path: string) => Promise<boolean>,
): AgentTool[] {
  const writingTools = ["write", "edit", "bash"];
  return tools.map((tool) =>
    writingTools.includes(tool.name) ? wrapTool(tool, tracker, cwd, confirmOverlap) : tool
  );
}

function wrapTool(
  tool: AgentTool,
  tracker: FileActivityTracker,
  cwd: string,
  confirmOverlap: (path: string) => Promise<boolean>,
): AgentTool {
  return {
    ...tool,
    execute: async (toolCallId, args, signal, onUpdate) => {
      const paths = extractWritePaths(tool.name, args);

      for (const path of paths) {
        if (tracker.hasWritten(path, cwd)) {
          const proceed = await confirmOverlap(path);
          if (!proceed) {
            return {
              content: [{ type: "text", text: `Skipped: ${path} (main agent has modified it)` }],
            };
          }
        }
      }

      return tool.execute(toolCallId, args, signal, onUpdate);
    },
  };
}

export function extractWritePaths(toolName: string, args: unknown): string[] {
  const record = args && typeof args === "object" ? (args as Record<string, unknown>) : {};

  switch (toolName) {
    case "write":
    case "edit":
      return typeof record.path === "string" ? [record.path] : [];
    case "bash":
      return typeof record.command === "string" ? parseBashWritePaths(record.command) : [];
    default:
      return [];
  }
}

function parseBashWritePaths(command: string): string[] {
  const tokens = tokenizeShell(command);
  const paths: string[] = [];
  let segment: ShellToken[] = [];

  for (const token of tokens) {
    if (token.type === "op" && isCommandSeparator(token.value)) {
      collectSegmentWritePaths(segment, paths);
      segment = [];
      continue;
    }
    segment.push(token);
  }

  collectSegmentWritePaths(segment, paths);
  return [...new Set(paths)];
}

type ShellToken =
  | { type: "word"; value: string }
  | { type: "op"; value: ">" | ">>" | "|" | "||" | "&" | "&&" | ";" };

function tokenizeShell(command: string): ShellToken[] {
  const tokens: ShellToken[] = [];

  for (let i = 0; i < command.length;) {
    const char = command[i];

    if (/\s/.test(char)) {
      i++;
      continue;
    }

    const twoCharOp = command.slice(i, i + 2);
    if (twoCharOp === ">>" || twoCharOp === "||" || twoCharOp === "&&") {
      tokens.push({ type: "op", value: twoCharOp });
      i += 2;
      continue;
    }

    if (char === ">" || char === "|" || char === "&" || char === ";") {
      tokens.push({ type: "op", value: char });
      i++;
      continue;
    }

    let value = "";
    while (i < command.length) {
      const current = command[i];

      if (/\s/.test(current) || current === ">" || current === "|" || current === "&" || current === ";") {
        break;
      }

      if (current === "\\") {
        if (i + 1 < command.length) {
          value += command[i + 1];
          i += 2;
        } else {
          i++;
        }
        continue;
      }

      if (current === "'") {
        i++;
        while (i < command.length && command[i] !== "'") {
          value += command[i];
          i++;
        }
        if (command[i] === "'") i++;
        continue;
      }

      if (current === '"') {
        i++;
        while (i < command.length && command[i] !== '"') {
          if (command[i] === "\\" && i + 1 < command.length && /["\\$`]/.test(command[i + 1])) {
            value += command[i + 1];
            i += 2;
          } else {
            value += command[i];
            i++;
          }
        }
        if (command[i] === '"') i++;
        continue;
      }

      value += current;
      i++;
    }

    if (value) tokens.push({ type: "word", value });
  }

  return tokens;
}

function collectSegmentWritePaths(segment: ShellToken[], paths: string[]): void {
  for (let i = 0; i < segment.length; i++) {
    const token = segment[i];
    if (token.type === "op" && (token.value === ">" || token.value === ">>")) {
      if (segment[i + 1]?.type === "word") {
        pushPath(paths, segment[i + 1].value);
        i++;
      }
    }
  }

  const commandIndex = segment.findIndex((token) => token.type === "word");
  if (commandIndex === -1) return;

  const command = segment[commandIndex];

  const operands = collectCommandOperands(segment.slice(commandIndex + 1));
  if (command.value === "tee" || command.value === "touch" || command.value === "rm") {
    for (const operand of operands) pushPath(paths, operand);
  }
  if ((command.value === "cp" || command.value === "mv") && operands.length >= 2) {
    pushPath(paths, operands[operands.length - 1]);
  }
}

function collectCommandOperands(tokens: ShellToken[]): string[] {
  const operands: string[] = [];
  let parsingOptions = true;

  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];

    if (token.type === "op") {
      if (token.value === ">" || token.value === ">>") {
        if (tokens[i + 1]?.type === "word") i++;
      }
      continue;
    }

    if (parsingOptions) {
      if (token.value === "--") {
        parsingOptions = false;
        continue;
      }
      if (token.value.startsWith("-")) {
        continue;
      }
      parsingOptions = false;
    }

    operands.push(token.value);
  }

  return operands;
}

function isCommandSeparator(value: ShellToken["value"]): boolean {
  return value === "|" || value === "||" || value === "&" || value === "&&" || value === ";";
}

function pushPath(paths: string[], path: string): void {
  if (path && !path.startsWith("-") && !isIgnoredWritePath(path)) {
    paths.push(path);
  }
}

function isIgnoredWritePath(path: string): boolean {
  return path === "/dev/null" || path === "/dev/stdout" || path === "/dev/stderr" || path.startsWith("/dev/fd/");
}

import type { AgentMessage } from "@mariozechner/pi-agent-core";
import { Key, matchesKey, wrapTextWithAnsi, type Component } from "@mariozechner/pi-tui";
import type { Theme } from "@mariozechner/pi-coding-agent";

const FRAMING_MESSAGE = Symbol("side-chat-framing");

export function markFramingMessage(message: AgentMessage): AgentMessage {
  Object.defineProperty(message, FRAMING_MESSAGE, { value: true });
  return message;
}

export function isFramingMessage(message: AgentMessage): boolean {
  return (message as AgentMessage & { [FRAMING_MESSAGE]?: boolean })[FRAMING_MESSAGE] === true;
}

export class SideChatMessages implements Component {
  private messages: AgentMessage[] = [];
  private streamingContent = "";
  private errorContent = "";
  private toolStatus = "";
  private scrollOffset = 0;
  private totalLines = 0;

  constructor(private theme: Theme, private maxVisibleLines: number) {}

  setMessages(messages: AgentMessage[]) {
    this.messages = messages;
    this.scrollOffset = 0;
  }

  setStreamingContent(content: string) {
    this.streamingContent = content;
    if (content) this.errorContent = "";
  }

  setErrorContent(content: string) {
    this.errorContent = content;
    if (content) this.streamingContent = "";
  }

  setToolStatus(status: string) {
    this.toolStatus = status;
  }

  setMaxVisibleLines(max: number) {
    this.maxVisibleLines = Math.max(1, max);
    this.scrollOffset = Math.min(this.scrollOffset, Math.max(0, this.totalLines - this.maxVisibleLines));
  }

  render(width: number): string[] {
    const lines: string[] = [];

    for (const msg of this.messages) {
      if (isFramingMessage(msg)) continue;
      const messageLines = this.renderMessage(msg, width);
      if (messageLines.length) {
        lines.push(...messageLines, "");
      }
    }

    if (this.errorContent) {
      lines.push(...wrapTextWithAnsi(this.theme.fg("error", "[Error]: ") + this.errorContent, width));
    } else if (this.streamingContent) {
      lines.push(...wrapTextWithAnsi(this.theme.fg("text", "[Assistant]: ") + this.streamingContent + "▌", width));
    }

    if (this.toolStatus) {
      if (lines.length) lines.push("");
      lines.push(...wrapTextWithAnsi(this.theme.fg("muted", `[Tool]: ${this.toolStatus}`), width));
    }

    this.totalLines = lines.length;
    const start = Math.max(0, lines.length - this.maxVisibleLines - this.scrollOffset);
    const end = Math.max(0, lines.length - this.scrollOffset);
    return lines.slice(start, end);
  }

  private renderMessage(msg: AgentMessage, width: number): string[] {
    const { theme } = this;

    if (msg.role === "user") {
      const content = typeof msg.content === "string" ? msg.content : msg.content.map((b) => b.type === "text" ? b.text : "[image]").join("");
      return wrapTextWithAnsi(theme.fg("accent", "[You]: ") + content, width);
    }

    if (msg.role === "assistant") {
      const text = msg.content.filter((b) => b.type === "text").map((b) => b.text).join("\n");
      if (text) return wrapTextWithAnsi(theme.fg("text", "[Assistant]: ") + text, width);
      if ("errorMessage" in msg && msg.errorMessage) {
        return wrapTextWithAnsi(theme.fg("error", "[Error]: ") + String(msg.errorMessage), width);
      }
      return [];
    }

    if (msg.role === "toolResult") {
      const fullText = msg.content[0]?.type === "text" ? msg.content[0].text : "";
      const preview = fullText.slice(0, 100);
      return wrapTextWithAnsi(theme.fg("muted", `[${msg.toolName}]: ${preview}${fullText.length > 100 ? "..." : ""}`), width);
    }

    if (msg.role === "branchSummary" || msg.role === "compactionSummary") {
      return wrapTextWithAnsi(theme.fg("muted", `[Summary]: ${msg.summary}`), width);
    }

    if (msg.role === "bashExecution") {
      return wrapTextWithAnsi(theme.fg("muted", `[Bash]: ${msg.command}`), width);
    }

    if (msg.role === "custom" && msg.display) {
      const content = typeof msg.content === "string" ? msg.content : msg.content.map((b) => b.type === "text" ? b.text : "[image]").join("");
      return wrapTextWithAnsi(theme.fg("muted", "[Context]: ") + content, width);
    }

    return [];
  }

  handleInput(data: string): boolean {
    if (matchesKey(data, Key.pageUp) || matchesKey(data, Key.shift("up"))) {
      this.scrollOffset = Math.min(this.scrollOffset + 5, Math.max(0, this.totalLines - this.maxVisibleLines));
      return true;
    }
    if (matchesKey(data, Key.pageDown) || matchesKey(data, Key.shift("down"))) {
      this.scrollOffset = Math.max(this.scrollOffset - 5, 0);
      return true;
    }
    return false;
  }

  invalidate() {}
}

import type { AgentMessage, AgentTool } from "@mariozechner/pi-agent-core";
import type { ExtensionAPI, ExtensionContext, ExtensionUIContext } from "@mariozechner/pi-coding-agent";
import type { Component, OverlayHandle, TUI } from "@mariozechner/pi-tui";
import { buildSessionContext, ExtensionRunner, getAgentDir } from "@mariozechner/pi-coding-agent";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { FileActivityTracker } from "./file-activity-tracker.ts";
import { getOverlayOptions } from "./side-chat-layout.ts";
import { SideChatOverlay, type ForkContext } from "./side-chat-overlay.ts";
import { extractWritePaths } from "./tool-wrapper.ts";

// Patch to capture the runner instance for extension tool access in side chat.
let capturedRunner: ExtensionRunner | null = null;
const origGetAllRegisteredTools = ExtensionRunner.prototype.getAllRegisteredTools;
ExtensionRunner.prototype.getAllRegisteredTools = function () {
  capturedRunner = this;
  return origGetAllRegisteredTools.call(this);
};

function getExtensionAgentTools(): AgentTool[] {
  if (!capturedRunner) return [];
  return capturedRunner.getAllRegisteredTools().map((rt): AgentTool => {
    const { definition } = rt;
    return {
      name: definition.name,
      label: definition.label,
      description: definition.description,
      parameters: definition.parameters,
      execute: (toolCallId, params, signal, onUpdate) =>
        definition.execute(toolCallId, params, signal, onUpdate, capturedRunner!.createContext()),
    };
  });
}

const DEFAULT_SHORTCUT = "alt+/";
const DEFAULT_FULLSCREEN_SHORTCUT = "alt+shift+m";
const OVERLAY_BLOCKED_ERROR = "PI_SIDE_CHAT_OVERLAY_BLOCKED";

type OverlayFocus = Pick<OverlayHandle, "focus" | "unfocus" | "isFocused">;
// OMP exposes the focused component on the TUI instead of focus methods on the overlay handle.
type FocusTUI = TUI & { getFocused?: () => Component | null };

function hasHandleFocus(handle: Partial<OverlayFocus>): handle is OverlayFocus {
  return typeof handle.focus === "function"
    && typeof handle.unfocus === "function"
    && typeof handle.isFocused === "function";
}

function getOverlayFocus(
  handle: OverlayHandle,
  tui: FocusTUI,
  overlay: SideChatOverlay,
  parent: Component | null,
): OverlayFocus {
  // Pi: keep using the host's overlay handle unchanged.
  if (hasHandleFocus(handle)) return handle;
  if (typeof tui.getFocused !== "function") {
    throw new Error("Side chat needs overlay handle focus methods or tui.getFocused()");
  }

  // OMP only lets focus leave a visible overlay for targets the overlay claims.
  // Claim the component that was focused before the side chat opened so it can
  // be refocused while the side chat stays visible.
  Object.assign(overlay, {
    ownsOverlayFocusTarget: (component: Component | null) => component === parent,
  });
  const getFocused = tui.getFocused.bind(tui);
  return {
    focus: () => {
      tui.setFocus(overlay);
      tui.requestRender();
    },
    unfocus: () => {
      tui.setFocus(parent);
      tui.requestRender();
    },
    isFocused: () => getFocused() === overlay,
  };
}

function loadConfig(): { shortcut: string; fullscreenShortcut: string } {
  const configPath = join(getAgentDir(), "pi-side-chat.json");
  try {
    const config = JSON.parse(readFileSync(configPath, "utf-8"));
    const shortcut = typeof config.shortcut === "string" ? config.shortcut.trim() : "";
    const fullscreenShortcut = typeof config.fullscreenShortcut === "string"
      ? config.fullscreenShortcut.trim()
      : "";
    return {
      shortcut: shortcut || DEFAULT_SHORTCUT,
      fullscreenShortcut: fullscreenShortcut || DEFAULT_FULLSCREEN_SHORTCUT,
    };
  } catch {
    return {
      shortcut: DEFAULT_SHORTCUT,
      fullscreenShortcut: DEFAULT_FULLSCREEN_SHORTCUT,
    };
  }
}

export default function sideChatExtension(pi: ExtensionAPI) {
  const config = loadConfig();
  const tracker = new FileActivityTracker();
  let activeOverlay: SideChatOverlay | null = null;
  let overlayFocus: OverlayFocus | null = null;
  let lastMessages: AgentMessage[] | null = null;

  pi.on("tool_execution_start", (event, ctx) => {
    if (["write", "edit", "bash"].includes(event.toolName)) {
      const paths = extractWritePaths(event.toolName, event.args);
      paths.forEach((p) => tracker.trackWrite(p, ctx.cwd));
    }
  });

  const toggleSideChat = async (ctx: ExtensionContext) => {
    if (activeOverlay) {
      if (overlayFocus?.isFocused()) {
        overlayFocus.unfocus();
      } else {
        overlayFocus?.focus();
      }
      return;
    }
    return openSideChat(ctx);
  };

  const openSideChat = async (ctx: ExtensionContext, clear = false) => {
    if (!ctx.model) {
      ctx.ui.notify("Cannot open side chat: no model configured", "error");
      return;
    }

    const sessionContext = buildSessionContext(ctx.sessionManager.getEntries(), ctx.sessionManager.getLeafId());
    const forkContext: ForkContext = {
      messages: clear ? [] : (lastMessages ?? sessionContext.messages),
      restored: !clear && lastMessages !== null,
      model: ctx.model,
      systemPrompt: ctx.getSystemPrompt(),
      thinkingLevel: pi.getThinkingLevel(),
      cwd: ctx.cwd,
      extensionTools: getExtensionAgentTools(),
    };
    const overlayOptions = getOverlayOptions("compact");
    let overlayTui: FocusTUI | null = null;
    let parentFocus: Component | null = null;

    try {
      const action = await ctx.ui.custom<"close" | "refork" | "clear">(
        (tui, theme, _keybindings, done) => {
          if (tui.hasOverlay()) {
            setTimeout(() => {
              ctx.ui.notify("Close or background the current overlay first", "warning");
            }, 0);
            throw new Error(OVERLAY_BLOCKED_ERROR);
          }

          overlayTui = tui;
          // Capture before the overlay exists so OMP can hand focus back to it.
          parentFocus = overlayTui.getFocused?.() ?? null;
          activeOverlay = new SideChatOverlay({
            tui,
            theme,
            forkContext,
            tracker,
            modelRegistry: ctx.modelRegistry,
            sessionManager: ctx.sessionManager,
            shortcut: config.shortcut,
            fullscreenShortcut: config.fullscreenShortcut,
            onDisplayModeChange: (mode) => {
              // pi-tui retains this object and reads its fields on each render.
              Object.assign(overlayOptions, getOverlayOptions(mode));
            },
            onOverlapWarning: (path) => showOverlapWarning(ctx.ui, path),
            onUnfocus: () => overlayFocus?.unfocus(),
            onClose: (action, messages) => {
              lastMessages = action === "close" ? messages : null;
              activeOverlay = null;
              overlayFocus = null;
              done(action);
            },
          });
          return activeOverlay;
        },
        {
          overlay: true,
          overlayOptions,
          onHandle: (handle) => {
            if (!activeOverlay || !overlayTui) return;
            overlayFocus = getOverlayFocus(handle, overlayTui, activeOverlay, parentFocus);
            overlayFocus.focus();
          },
        },
      );
      if (action === "refork") return openSideChat(ctx);
      if (action === "clear") return openSideChat(ctx, true);
    } catch (error) {
      if (error instanceof Error && error.message === OVERLAY_BLOCKED_ERROR) {
        return;
      }
      activeOverlay = null;
      overlayFocus = null;
      throw error;
    }
  };

  pi.registerShortcut(config.shortcut, {
    description: "Toggle side chat focus (open if closed)",
    handler: toggleSideChat,
  });

  pi.registerShortcut(config.fullscreenShortcut, {
    description: "Toggle side chat fullscreen mode",
    handler: () => activeOverlay?.toggleDisplayMode(),
  });

  pi.registerCommand("side", {
    description: "Open side chat (fork conversation)",
    handler: (_, ctx) => toggleSideChat(ctx),
  });
}

function showOverlapWarning(ui: ExtensionUIContext, path: string): Promise<boolean> {
  return ui.confirm(
    "File Overlap",
    `Main agent has modified:\n  ${path}\n\nEditing may cause conflicts. Proceed?`
  );
}

import { randomUUID } from "node:crypto";
import { Agent, type AgentEvent, type AgentMessage, type AgentTool, type ThinkingLevel } from "@mariozechner/pi-agent-core";
import type { Model } from "@mariozechner/pi-ai";
import {
  buildSessionContext,
  convertToLlm,
  createCodingTools,
  createReadOnlyTools,
  getSelectListTheme,
  type ModelRegistry,
  type SessionManager,
  type Theme,
} from "@mariozechner/pi-coding-agent";
import { Type } from "@sinclair/typebox";
import { Editor, Key, matchesKey, truncateToWidth, visibleWidth, type Component, type Focusable, type TUI } from "@mariozechner/pi-tui";
import type { FileActivityTracker } from "./file-activity-tracker.ts";
import { forkSurgery } from "./fork-surgery.ts";
import { getMaxMessageLines, type DisplayMode } from "./side-chat-layout.ts";
import { isFramingMessage, markFramingMessage, SideChatMessages } from "./side-chat-messages.ts";
import { wrapToolsWithOverlapDetection } from "./tool-wrapper.ts";

export interface ForkContext {
  messages: AgentMessage[];
  restored?: boolean;
  model: Model<any>;
  systemPrompt: string;
  thinkingLevel: ThinkingLevel;
  cwd: string;
  extensionTools: AgentTool[];
}

interface SideChatOverlayOptions {
  tui: TUI;
  theme: Theme;
  forkContext: ForkContext;
  tracker: FileActivityTracker;
  modelRegistry: ModelRegistry;
  sessionManager: SessionManager;
  shortcut: string;
  fullscreenShortcut: string;
  onDisplayModeChange: (mode: DisplayMode) => void;
  onOverlapWarning: (path: string) => Promise<boolean>;
  onUnfocus: () => void;
  onClose: (action: "close" | "refork" | "clear", messages: AgentMessage[]) => void;
}

const SIDE_CHAT_PROMPT = `
---
## Side Chat

You're in a SIDE CHAT parallel to the main agent. Main is working independently and can't see this.

Use \`peek_main\` to see main's activity when user asks about progress or you need context.
Use \`peek_main({ since_fork: true })\` for activity since side chat opened.

The copied main context is reference only. Do not continue its pending user request, tool call, reasoning, edits, or unfinished answer. Answer the latest user message in this side chat.

Be concise - this is for quick questions. If user wants something main is doing, suggest waiting.`;

const SPINNER = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];

// Key lookup for registries without streamSimple (such as OMP's): the Agent then streams
// itself and asks for keys by model or by provider name.
interface ApiKeyRegistry {
  getApiKey(model: Model<any>): Promise<string | undefined>;
  getApiKeyForProvider(provider: string): Promise<string | undefined>;
}

export class SideChatOverlay implements Component, Focusable {
  private agent: Agent;
  private messages: SideChatMessages;
  private editor: Editor;
  private isStreaming = false;
  private streamingContent = "";
  private toolMode: "full" | "read-only" = "read-only";
  private displayMode: DisplayMode = "compact";
  private _focused = true;
  private disposed = false;
  private forkLeafId: string | null;
  private peekMainTool: AgentTool;
  private spinnerInterval: NodeJS.Timeout | null = null;
  private spinnerFrame = 0;

  get focused() { return this._focused; }
  set focused(v: boolean) { this._focused = v; this.editor.focused = v; }

  constructor(private options: SideChatOverlayOptions) {
    const { tui, theme, forkContext, modelRegistry, sessionManager } = options;
    const forkedMessages = forkContext.restored
      ? JSON.parse(JSON.stringify(forkContext.messages)) as AgentMessage[]
      : forkSurgery(JSON.parse(JSON.stringify(forkContext.messages)) as AgentMessage[]);
    const framingMessage = forkContext.restored
      ? undefined
      : markFramingMessage({
        role: "user",
        content: "The preceding messages are copied main-session context for reference only. Answer the latest side-chat user message; do not resume the main lane's pending work.",
        timestamp: Date.now(),
      });
    const initialTools = createReadOnlyTools(forkContext.cwd);

    this.forkLeafId = sessionManager.getLeafId();
    this.peekMainTool = this.createPeekMainTool(sessionManager);

    // Pi stores "off" as a thinking level; OMP separates effort from disabling reasoning.
    const usesEffortState = "setDisableReasoning" in Agent.prototype;
    const thinkingOff = forkContext.thinkingLevel === "off";
    const registry = modelRegistry as ModelRegistry & ApiKeyRegistry;

    // Pi's options type requires streamFn; Agents that stream themselves accept getApiKey instead.
    this.agent = new Agent({
      initialState: {
        systemPrompt: forkContext.systemPrompt + SIDE_CHAT_PROMPT,
        model: forkContext.model,
        ...(usesEffortState
          ? { thinkingLevel: thinkingOff ? undefined : forkContext.thinkingLevel, disableReasoning: thinkingOff }
          : { thinkingLevel: forkContext.thinkingLevel }),
        tools: [...initialTools, ...forkContext.extensionTools, this.peekMainTool],
        messages: framingMessage ? [...forkedMessages, framingMessage] : forkedMessages,
      },
      convertToLlm,
      // The registry resolves credentials per request; only hosts without it get a key callback.
      ...(typeof registry.streamSimple === "function"
        ? { streamFn: (model, context, streamOptions) => registry.streamSimple(model, context, streamOptions) }
        : {
          getApiKey: async (target: string | Model<any>) => {
            const provider = typeof target === "string" ? target : target.provider;
            const key = typeof target === "string"
              ? await registry.getApiKeyForProvider(target)
              : await registry.getApiKey(target);
            if (!key) throw new Error(`No API key available for provider "${provider}"`);
            return key;
          },
        }),
      sessionId: randomUUID(),
    } as ConstructorParameters<typeof Agent>[0]);

    this.agent.subscribe((e) => this.handleAgentEvent(e));
    this.messages = new SideChatMessages(theme, 20);
    this.messages.setMessages(forkedMessages);
    const editorTheme = { borderColor: (t: string) => theme.fg("borderMuted", t), selectList: getSelectListTheme() };
    // OMP's select-list theme carries symbols and its Editor takes only a complete theme.
    if ("symbols" in editorTheme.selectList) {
      const ompTheme = { ...editorTheme, symbols: editorTheme.selectList.symbols };
      const OmpEditor = Editor as unknown as new (theme: typeof ompTheme) => Editor & { setPaddingX(padding: number): void };
      const editor = new OmpEditor(ompTheme);
      editor.setPaddingX(0);
      this.editor = editor;
    } else {
      this.editor = new Editor(tui, editorTheme, { paddingX: 0 });
    }
    this.editor.onSubmit = (text) => this.handleSubmit(text);
  }

  private createPeekMainTool(sessionManager: SessionManager): AgentTool {
    return {
      name: "peek_main",
      label: "peek_main",
      description: "View main agent's recent activity. Use when user asks about main's progress or status.",
      parameters: Type.Object({
        lines: Type.Optional(Type.Integer({ description: "Max items (default: 20)", minimum: 1, maximum: 50 })),
        since_fork: Type.Optional(Type.Boolean({ description: "Only show activity after side chat opened" })),
      }),
      execute: async (_id, args: { lines?: number; since_fork?: boolean }) => {
        const entries = sessionManager.getEntries();
        const context = buildSessionContext(entries, sessionManager.getLeafId());
        let msgs = context.messages;

        if (args.since_fork && this.forkLeafId) {
          const forkCtx = buildSessionContext(entries, this.forkLeafId);
          msgs = msgs.slice(forkCtx.messages.length);
        }

        const recent = msgs.slice(-(args.lines ?? 20));
        if (!recent.length) {
          return { content: [{ type: "text", text: args.since_fork ? "No new activity since fork." : "No recent activity." }] };
        }

        const formatted = recent.map((m) => this.formatMessage(m)).filter(Boolean).join("\n\n");
        return { content: [{ type: "text", text: `Main agent activity (${recent.length} items):\n\n${formatted}` }] };
      },
    };
  }

  private formatMessage(msg: AgentMessage): string {
    if (msg.role === "user") {
      const c = typeof msg.content === "string" ? msg.content : msg.content.map((b) => b.type === "text" ? b.text : "[image]").join("");
      return `[User]: ${c.slice(0, 300)}${c.length > 300 ? "..." : ""}`;
    }
    if (msg.role === "assistant") {
      const fullText = msg.content.filter((b) => b.type === "text").map((b) => b.text).join("\n");
      const text = fullText.slice(0, 500);
      const tools = msg.content.filter((b) => b.type === "tool_call").map((t) => t.toolName);
      const parts = [text && (text + (fullText.length > 500 ? "..." : "")), tools.length && `[Calling: ${tools.join(", ")}]`].filter(Boolean);
      return parts.length ? `[Assistant]: ${parts.join("\n")}` : "";
    }
    if (msg.role === "toolResult") {
      const fullText = msg.content[0]?.type === "text" ? msg.content[0].text : "";
      const preview = fullText.slice(0, 150);
      return `[${msg.toolName}]: ${preview}${fullText.length > 150 ? "..." : ""}`;
    }
    return "";
  }

  private startSpinner() {
    this.stopSpinner();
    this.spinnerFrame = 0;
    this.messages.setToolStatus(`${SPINNER[0]} Working...`);
    this.options.tui.requestRender();
    this.spinnerInterval = setInterval(() => {
      this.spinnerFrame = (this.spinnerFrame + 1) % SPINNER.length;
      this.messages.setToolStatus(`${SPINNER[this.spinnerFrame]} Working...`);
      this.options.tui.requestRender();
    }, 80);
  }

  private stopSpinner() {
    if (!this.spinnerInterval) return;
    clearInterval(this.spinnerInterval);
    this.spinnerInterval = null;
    this.messages.setToolStatus("");
  }

  private async handleSubmit(text: string) {
    const trimmed = text.trim();
    if (!trimmed || this.isStreaming || this.disposed) return;

    this.editor.setText("");
    this.isStreaming = true;
    this.streamingContent = "";
    this.messages.setStreamingContent("");
    this.messages.setErrorContent("");
    this.startSpinner();

    try {
      await this.agent.prompt(trimmed);
    } catch (e) {
      this.streamingContent = "";
      if (!this.disposed) {
        this.messages.setErrorContent(e instanceof Error ? e.message : "Unknown error");
      }
    } finally {
      this.isStreaming = false;
      this.streamingContent = "";
      this.stopSpinner();
      this.messages.setStreamingContent("");
      this.messages.setToolStatus("");
      this.messages.setMessages([...this.agent.state.messages]);
      if (!this.disposed) this.options.tui.requestRender();
    }
  }

  private handleAgentEvent(event: AgentEvent) {
    if (this.disposed) return;

    if (event.type === "message_update" && event.assistantMessageEvent?.type === "text_delta") {
      this.stopSpinner();
      this.streamingContent += event.assistantMessageEvent.delta;
      this.messages.setStreamingContent(this.streamingContent);
    } else if (event.type === "message_end") {
      this.messages.setMessages([...this.agent.state.messages]);
      this.messages.setStreamingContent("");
      this.streamingContent = "";
    } else if (event.type === "tool_execution_start") {
      this.stopSpinner();
      this.messages.setToolStatus(`Running ${event.toolName}...`);
    } else if (event.type === "tool_execution_end") {
      this.startSpinner();
    }

    this.options.tui.requestRender();
  }

  render(width: number): string[] {
    if (width < 4) {
      return [" ".repeat(Math.max(0, width))];
    }

    const { theme, tracker } = this.options;
    const innerWidth = width - 4;
    const lines: string[] = [];
    const borderColor = this._focused ? "border" : "borderMuted";

    const title = "Side Chat";
    const focusHint = this._focused ? "" : " (unfocused)";
    const mainLabel = tracker.writeCount ? `${tracker.writeCount} file${tracker.writeCount > 1 ? "s" : ""}` : "idle";
    const modeLabel = this.toolMode === "full" ? "Edit" : "Read-only";
    const modeColor = this.toolMode === "full" ? "warning" : "dim";
    const status = theme.fg("dim", `[Main: ${mainLabel}] `) + theme.fg(modeColor, `[${modeLabel}]`);
    const stream = this.isStreaming ? theme.fg("warning", " ●") : "";
    const left = theme.fg(this._focused ? "accent" : "dim", title) + theme.fg("dim", focusHint) + stream;
    const leftWidth = Math.max(1, innerWidth - visibleWidth(status) - 1);
    const headerLeft = truncateToWidth(left, leftWidth);
    const headerGap = " ".repeat(Math.max(1, innerWidth - visibleWidth(headerLeft) - visibleWidth(status)));

    lines.push(theme.fg(borderColor, "┌" + "─".repeat(width - 2) + "┐"));
    lines.push(this.frameLine(`${headerLeft}${headerGap}${status}`, innerWidth, theme, borderColor));
    lines.push(theme.fg(borderColor, "├" + "─".repeat(width - 2) + "┤"));

    const renderedEditorLines = this.editor.render(innerWidth);
    const editorLines = this.displayMode === "fullscreen"
      ? renderedEditorLines.slice(0, Math.max(0, this.options.tui.terminal.rows - 7))
      : renderedEditorLines;
    const maxLines = getMaxMessageLines(
      this.options.tui.terminal.rows,
      this.displayMode,
      editorLines.length,
    );
    this.messages.setMaxVisibleLines(maxLines);
    const msgLines = maxLines > 0 ? this.messages.render(innerWidth) : [];
    for (const line of msgLines) lines.push(this.frameLine(line, innerWidth, theme, borderColor));
    for (let i = msgLines.length; i < maxLines; i++) lines.push(this.frameLine("", innerWidth, theme, borderColor));

    lines.push(theme.fg(borderColor, "├" + "─".repeat(width - 2) + "┤"));
    for (const line of editorLines) {
      lines.push(this.frameLine(line, innerWidth, theme, borderColor));
    }

    const shortcutLabel = this.formatShortcut(this.options.shortcut);
    const fullscreenLabel = this.formatShortcut(this.options.fullscreenShortcut);
    const escHint = this.isStreaming ? "Esc stop" : "Esc close";
    const displayHint = this.displayMode === "fullscreen" ? "restore" : "fullscreen";
    const modeHint = this.toolMode === "read-only" ? "Ctrl+T → edit mode" : "Ctrl+T → read-only";
    const hints = this._focused
      ? `${escHint} · Enter send · ${fullscreenLabel} ${displayHint} · Alt+R refork · Alt+N clear · ${shortcutLabel} → unfocus · ${modeHint}`
      : `${shortcutLabel} → focus side chat · ${fullscreenLabel} ${displayHint}`;
    lines.push(theme.fg(borderColor, "├" + "─".repeat(width - 2) + "┤"));
    lines.push(this.frameLine(theme.fg("dim", hints), innerWidth, theme, borderColor));
    lines.push(theme.fg(borderColor, "└" + "─".repeat(width - 2) + "┘"));

    const rendered = lines.map((l) => visibleWidth(l) > width ? truncateToWidth(l, width) : l);
    return this.displayMode === "fullscreen"
      ? rendered.slice(0, Math.max(0, this.options.tui.terminal.rows))
      : rendered;
  }

  private frameLine(line: string, width: number, theme: Theme, borderColor: string): string {
    return theme.fg(borderColor, "│ ") + truncateToWidth(line, width, "...", true) + theme.fg(borderColor, " │");
  }

  private replaceAgentTools(tools: AgentTool[]): void {
    const legacyAgent = this.agent as Agent & { setTools?: (tools: AgentTool[]) => void };
    if (typeof legacyAgent.setTools === "function") {
      legacyAgent.setTools(tools);
      return;
    }
    this.agent.state.tools = tools;
  }

  private formatShortcut(shortcut: string): string {
    return shortcut
      .split("+")
      .map((part) => {
        const lower = part.toLowerCase();
        if (lower === "ctrl") return "Ctrl";
        if (lower === "shift") return "Shift";
        if (lower === "alt") return "Alt";
        return part.length === 1 ? part.toUpperCase() : part;
      })
      .join("+");
  }

  toggleDisplayMode(): void {
    this.displayMode = this.displayMode === "compact" ? "fullscreen" : "compact";
    this.options.onDisplayModeChange(this.displayMode);
    this.options.tui.requestRender();
  }

  handleInput(data: string): void {
    if (matchesKey(data, Key.escape)) {
      if (this.isStreaming) {
        this.agent.abort();
      } else {
        this.dispose();
      }
      return;
    }
    if (matchesKey(data, this.options.shortcut)) { this.options.onUnfocus(); return; }
    if (matchesKey(data, this.options.fullscreenShortcut)) { this.toggleDisplayMode(); return; }
    if (matchesKey(data, Key.alt("r"))) { this.dispose("refork"); return; }
    if (matchesKey(data, Key.alt("n"))) { this.dispose("clear"); return; }
    if (matchesKey(data, Key.ctrl("t"))) {
      const nextMode = this.toolMode === "full" ? "read-only" : "full";
      const { forkContext, tracker, onOverlapWarning } = this.options;
      const builtinTools = nextMode === "read-only"
        ? createReadOnlyTools(forkContext.cwd)
        : wrapToolsWithOverlapDetection(createCodingTools(forkContext.cwd), tracker, forkContext.cwd, onOverlapWarning);

      this.replaceAgentTools([...builtinTools, ...forkContext.extensionTools, this.peekMainTool]);
      this.toolMode = nextMode;
      this.options.tui.requestRender();
      return;
    }
    if (this.messages.handleInput(data)) { this.options.tui.requestRender(); return; }
    this.editor.handleInput(data);
    this.options.tui.requestRender();
  }

  dispose(action: "close" | "refork" | "clear" = "close") {
    if (this.disposed) return;
    this.disposed = true;
    this.stopSpinner();
    const messages = this.agent.state.messages.filter((message) => !isFramingMessage(message));
    this.agent.abort();
    this.options.onClose(action, messages);
  }

  invalidate() {
    this.messages.invalidate();
    this.editor.invalidate();
  }
}
